function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 100) return 'The grid needs 1 to 100 rows.';
  const cols = grid[0].length;
  if (cols < 1 || cols > 100) return 'The grid needs 1 to 100 columns.';
  for (const row of grid) {
    if (row.length !== cols) return 'Every row must have the same length.';
    if (row.some(v => v !== 1 && v !== -1)) return 'Each cell is 1 or -1.';
  }
  return null;
}

