function findBall(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const answer = [];

  for (let start = 0; start < cols; start++) {
    let col = start;
    for (let row = 0; row < rows && col !== -1; row++) {
      const dir = grid[row][col];
      const next = col + dir;
      if (next < 0 || next >= cols || grid[row][next] !== dir) {
        col = -1;
      } else {
        col = next;
      }
    }
    answer.push(col);
  }
  return answer;
}

