function findBall(grid) {
  // Each board splits its cell into two triangles; follow the ball from triangle to triangle.
  // A ball enters a cell from the top, the left or the right side.
  const rows = grid.length, cols = grid[0].length;
  const drop = (start) => {
    let row = 0, col = start, side = 'top';
    for (let steps = 0; steps < 4 * rows * cols + 4; steps++) {
      if (col < 0 || col >= cols) return -1;
      if (row === rows) return col;
      const board = grid[row][col];
      if (side === 'top') {
        // '\' puts the top in the upper-right triangle (open to the right), '/' in the upper-left one.
        if (board === 1) { col += 1; side = 'left'; } else { col -= 1; side = 'right'; }
      } else if (side === 'left') {
        // Entering from the left: under '\' the triangle's floor is open, under '/' it is a dead end.
        if (board === 1) { row += 1; side = 'top'; } else return -1;
      } else {
        if (board === -1) { row += 1; side = 'top'; } else return -1;
      }
    }
    return -1;
  };
  const result = [];
  for (let c = 0; c < cols; c++) result.push(drop(c));
  return result;
}

