function generate(rand, size) {
  const large = size === 'large';
  const rows = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const cols = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const grid = [];
  for (let r = 0; r < rows; r++) {
    // Each row is made of runs of equal boards; on large grids most rows are a single run so some balls get through.
    const switchChance = large ? (rand() < 0.75 ? 0 : 0.05) : rand() * 0.6;
    let dir = rand() < 0.5 ? 1 : -1;
    const row = [];
    for (let c = 0; c < cols; c++) {
      if (c > 0 && rand() < switchChance) dir = -dir;
      row.push(dir);
    }
    grid.push(row);
  }
  return [grid];
}
